def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float))

    def to_xy(v):
        if isinstance(v, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if kx in v and ky in v and is_num(v.get(kx)) and is_num(v.get(ky)):
                    return [int(v.get(kx)), int(v.get(ky))]
        elif isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def first_pos(obj):
        if obj is None:
            return None
        p = to_xy(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for key in ("position", "pos", "loc", "location", "me", "agent", "self"):
                p = first_pos(obj.get(key))
                if p is not None:
                    return p
        return None

    def collect_positions(obj, out):
        if obj is None:
            return
        p = to_xy(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_positions(v, out)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                collect_positions(v, out)

    def clamp_step(d):
        if d > 0:
            return 1
        if d < 0:
            return -1
        return 0

    me = None
    for key in ("position", "pos", "location", "loc", "agent_position", "self_position", "player_position"):
        me = first_pos(observation.get(key))
        if me is not None:
            break
    if me is None:
        me = first_pos(observation.get("self")) or first_pos(observation.get("agent")) or first_pos(observation.get("player"))
    if me is None:
        me = [0, 0]

    # infer board center/bounds if available
    w = h = None
    for key in ("grid", "board", "map", "world"):
        g = observation.get(key)
        if isinstance(g, (list, tuple)) and g:
            h = len(g)
            if isinstance(g[0], (list, tuple)):
                w = len(g[0])
            break
    if w is None or h is None:
        size = observation.get("size")
        if isinstance(size, (list, tuple)) and len(size) >= 2 and is_num(size[0]) and is_num(size[1]):
            w, h = int(size[0]), int(size[1])

    targets = []
    # resource_collection
    for key in ("resources", "resource_positions", "collectibles", "items", "food", "gold", "gems"):
        collect_positions(observation.get(key), targets)

    # pursuit_evasion / territory_control adversaries
    enemies = []
    for key in ("enemies", "opponents", "enemy_positions", "agents", "players", "others", "threats", "prey", "chasers"):
        collect_positions(observation.get(key), enemies)

    # territory related
    territory = []
    for key in ("territory", "owned", "control", "cells", "frontier", "empty"):
        collect_positions(observation.get(key), territory)

    # If explicit target/goal exists, prefer it
    for key in ("target", "goal", "destination", "objective"):
        p = first_pos(observation.get(key))
        if p is not None:
            targets.append(p)

    def nearest(points, from_xy):
        best = None
        best_d = None
        fx, fy = from_xy
        for p in points:
            dx = p[0] - fx
            dy = p[1] - fy
            d = dx * dx + dy * dy
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    # Detect danger from close enemy
    danger = None
    danger_d = None
    if enemies:
        danger, danger_d = nearest(enemies, me)

    # territory_control heuristic: if no resources, move toward nearest enemy-adjacent frontier or center
    if targets:
        tgt, _ = nearest(targets, me)
        dx = clamp_step(tgt[0] - me[0])
        dy = clamp_step(tgt[1] - me[1])
        return [dx, dy]

    if danger is not None and danger_d is not None and danger_d <= 4:
        # flee from nearest threat
        dx = clamp_step(me[0] - danger[0])
        dy = clamp_step(me[1] - danger[1])
        if dx == 0 and dy == 0:
            dx = 1
        return [dx, dy]

    if enemies:
        # pursuit_evasion or simple chase: move toward nearest enemy if safe
        tgt, _ = nearest(enemies, me)
        dx = clamp_step(tgt[0] - me[0])
        dy = clamp_step(tgt[1] - me[1])
        if dx == 0 and dy == 0:
            dx = 1
        return [dx, dy]

    if territory:
        tgt, _ = nearest(territory, me)
        dx = clamp_step(tgt[0] - me[0])
        dy = clamp_step(tgt[1] - me[1])
        return [dx, dy]

    # fallback: explore toward center / diagonal
    if w is not None and h is not None:
        cx = w // 2
        cy = h // 2
        dx = clamp_step(cx - me[0])
        dy = clamp_step(cy - me[1])
        if dx == 0 and dy == 0:
            dx = 1
        return [dx, dy]

    return [1, 0]

